import random
import string

store = {}

def shorten(url):
    alphabet = string.ascii_letters + string.digits
    code = ''.join(random.choice(alphabet) for _ in range(6))
    while code in store:
        code = ''.join(random.choice(alphabet) for _ in range(6))
    store[code] = url
    return code

def expand(code):
    return store.get(code)

if __name__ == '__main__':
    c = shorten('https://example.com/a/very/long/path')
    print(c, expand(c))
